python3 -I - <<'EOF'
import re
p='crates/athena-git/src/lib.rs'
s=open(p).read()
a=s.index("    /// A commit on top of `base` whose tree is `base`'s")
b=s.index("    /// Three-way merges `theirs` into `ours`")
new='''    /// A regular push of `commit` to `refs/heads/{branch}` on `remote`; git refuses anything but a
    /// fast-forward.
    pub fn push_branch(&self, remote: &str, branch: &str, commit: &str) -> Result<()> {
        self.run(["push", remote, &format!("{commit}:refs/heads/{branch}")])?;
        Ok(())
    }

    /// Replaces `refs/heads/{branch}` on `remote` with `commit`, a forced push that is conditional: it
    /// proceeds only while the remote branch still holds `expected`, the head the caller observed. When the
    /// branch moved since, nothing is pushed and the call fails.
    pub fn push_replace(
        &self,
        remote: &str,
        branch: &str,
        commit: &str,
        expected: &str,
    ) -> Result<()> {
        let refname = format!("refs/heads/{branch}");
        let listing = self.run(["ls-remote", "--heads", remote, &refname])?;
        let now = listing
            .lines()
            .next()
            .and_then(|l| l.split_whitespace().next());
        if now != Some(expected) {
            return Err(GitError::Parse(format!(
                "the remote branch {branch} moved since it was read; nothing was pushed"
            )));
        }
        self.run(["push", remote, &format!("+{commit}:{refname}")])?;
        Ok(())
    }

'''
s=s[:a]+new+s[b:]
a=s.index("    #[test]\n    fn commit_with_records_adds")
b=s.index("    #[test]\n    fn trailers_are_parsed")
test='''    #[test]
    fn push_replace_forces_only_while_the_remote_head_is_the_expected_one() {
        let (_dir, git) = repo_with(&[("a.txt", "a")]);
        let first = git.head().unwrap().unwrap();
        let bare = tempfile::tempdir().unwrap();
        git.run(["init", "-q", "--bare", &bare.path().display().to_string()])
            .unwrap();
        let url = bare.path().display().to_string();
        git.push_branch(&url, "athena/x", &first).unwrap();
        let remote_head = || {
            let out = git
                .run(["ls-remote", "--heads", &url, "refs/heads/athena/x"])
                .unwrap();
            out.split_whitespace().next().unwrap().to_string()
        };
        assert_eq!(remote_head(), first);

        // A rewritten history: the plain push refuses, the replace goes through.
        git.run(["checkout", "-q", "--orphan", "other"]).unwrap();
        let rewritten = commit_all(&git, "rewritten");
        assert!(git.push_branch(&url, "athena/x", &rewritten).is_err());
        assert_eq!(remote_head(), first);

        // The branch moved from what the caller read: nothing is pushed.
        let stale = "0123456789abcdef0123456789abcdef01234567";
        assert!(
            git.push_replace(&url, "athena/x", &rewritten, stale)
                .is_err()
        );
        assert_eq!(remote_head(), first);

        git.push_replace(&url, "athena/x", &rewritten, &first)
            .unwrap();
        assert_eq!(remote_head(), rewritten);
    }

'''
s=s[:a]+test+s[b:]
open(p,'w').write(s)
EOF
